#!/usr/bin/env node
// Runs Python tooling for backend/ with the right interpreter, from any OS.
//
//   node tools/py.mjs setup                     create .venv and install backend/ with dev tools
//   node tools/py.mjs -m pytest -q backend/tests  run a Python module from the repository root
//
// Interpreter order: $APP_PYTHON, .venv, then python3 / python on PATH. The harness gates
// (npm run lint / typecheck / test / build) call this launcher so they behave the same on
// Windows, macOS and Linux. Generated by ai-app-chassis create-app.

import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

function works(cmd) {
  return spawnSync(cmd, ["--version"], { stdio: "ignore" }).status === 0;
}

function systemPython() {
  return ["python3", "python"].find(works) ?? "";
}

function venvPython() {
  const candidates = [
    path.join(root, ".venv", "bin", "python"),
    path.join(root, ".venv", "Scripts", "python.exe"),
  ];
  return candidates.find((candidate) => existsSync(candidate)) ?? "";
}

function run(cmd, args) {
  return spawnSync(cmd, args, { cwd: root, stdio: "inherit" }).status ?? 1;
}

const args = process.argv.slice(2);

if (args[0] === "setup") {
  const python = process.env.APP_PYTHON || systemPython();
  if (!python) {
    console.error("No Python interpreter found (need Python >= 3.11 on PATH).");
    process.exit(1);
  }
  if (!venvPython() && run(python, ["-m", "venv", ".venv"]) !== 0) process.exit(1);
  process.exit(run(venvPython(), ["-m", "pip", "install", "--quiet", "-e", "./backend[dev]"]));
}

const python = process.env.APP_PYTHON || venvPython() || systemPython();
if (!python) {
  console.error("No Python interpreter found (need Python >= 3.11 on PATH).");
  process.exit(1);
}
const ready = spawnSync(python, ["-c", "import {{package}}, ai_app_chassis, fastapi, pytest, mypy, ruff"], {
  cwd: root,
  stdio: "ignore",
}).status === 0;
if (!ready) {
  console.error("Python dependencies are not installed. Run: npm run setup:python");
  process.exit(1);
}
process.exit(run(python, args));
